package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class CircleLengthRelationsTest {
 private List<Rational> values(Question q){Matcher m=Pattern.compile("\\d+(?:\\.\\d+)?(?:/\\d+)?").matcher(q.prompt);assertTrue(m.find());Rational r=Expression.number(m.group());if(q.skillId.endsWith("chord"))return List.of(r,r.mul(Rational.of(2)));assertTrue(m.find());Rational d=Expression.number(m.group()),ds=d.mul(d),rs=r.mul(r),diff=ds.sub(rs);assertTrue(r.compareTo(Rational.ZERO)>0&&d.compareTo(r)>0);Rational length=diff.sqrt();assertEquals(ds,length.mul(length).add(rs));return List.of(r,d,ds,rs,diff,length);}
 @Test public void publicLengthsDetermineEveryStepAndMore100SmallProblemsPerUnit(){Generator g=new Generator(new Random(2070));for(String id:List.of("sec_circle_chord","sec_circle_tangent")){Set<String> prompts=new HashSet<>(),answers=new HashSet<>();Set<Integer> positions=new HashSet<>();boolean noninteger=false;for(int i=0;i<1200;i++){Question q=g.next(id,List.of(),i%2==0);var v=values(q);Rational result=v.get(v.size()-1);assertTrue(new Checker().check(q,List.of(),List.of(result.toString())).correct());prompts.add(q.prompt);answers.add(result.toString());positions.add(q.correctChoice);noninteger|=!result.isInteger();assertTrue(v.get(0).compareTo(Rational.of(id.endsWith("chord")?15:50))<=0);if(id.endsWith("tangent"))assertTrue(v.get(1).compareTo(Rational.of(50))<=0);verify(q,v);}assertTrue(id,prompts.size()>100);assertTrue(id,answers.size()>(id.endsWith("chord")?100:40));assertTrue(noninteger);assertTrue(positions.containsAll(Set.of(0,1,2,3)));}}
 private void verify(Question q,List<Rational> v){String signature=q.signature();StudyDiagram old=q.diagram;Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertSame(old,q.diagram);assertFalse(p.canTransfer());assertEquals(v.size(),p.size());for(int i=0;i<v.size();i++){assertTrue(p.step(i).accepts(v.get(i).toString()));assertTrue(p.step(i).accepts(v.get(i).decimalText()));assertFalse(p.step(i).accepts(v.get(i).add(Rational.ONE).toString()));assertEquals("",p.step(i).after);}assertEquals(q.skillId.endsWith("chord")?"AM × 2 = ":"√(접선 길이의 제곱값) = ",p.step(p.size()-1).before);}
 @Test public void savedFractionsAndOldCalculatedSquareDraftRemainExact(){Question chord=new Question("sec_circle_chord","원의 중심 O에서 현 AB에 내린 수선의 발을 M이라 할 때 AM=7/3입니다. 현 AB의 길이는?","","14/3");verify(chord,values(chord));Question tangent=new Question("sec_circle_tangent","원의 반지름이 3/7, 중심에서 원 밖의 점까지 거리가 5/7일 때 그 점에서 그은 접선의 길이는?","","4/7");verify(tangent,values(tangent));Question q=new Question("sec_circle_tangent","원의 반지름이 3, 중심에서 원 밖의 점까지 거리가 5일 때 그 점에서 그은 접선의 길이는?","","4");HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("16",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"3");d.stage=1;var restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("3",restored.entries.get(0));}
}
